+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * Which customers a query asks for: a name search and a set of statuses. A customer
+ * is matched when it satisfies both.
+ *
+ * @param nameTerms the name search, folded and split on whitespace (see {@link #of});
+ *                  every term must appear in the customer's first or last name
+ * @param statuses  the statuses to match; empty matches every status
+ */
+public record CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter ALL = new CustomerFilter(List.of(), Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        nameTerms = List.copyOf(nameTerms);
+        statuses = Set.copyOf(statuses);
+    }
+
+    /**
+     * Builds a filter from what the user typed. The name is split on whitespace, and
+     * matching ignores case and accents. An empty name matches every customer.
+     */
+    public static CustomerFilter of(String name, Set<CustomerStatus> statuses) {
+        List<String> terms = WHITESPACE.splitAsStream(fold(name).strip())
+                .filter(term -> !term.isEmpty())
+                .toList();
+        return new CustomerFilter(terms, statuses);
+    }
+
+    /** Whether {@code customer} satisfies both the name search and the status filter. */
+    public boolean matches(Customer customer) {
+        return matchesName(customer) && (statuses.isEmpty() || statuses.contains(customer.status()));
+    }
+
+    private boolean matchesName(Customer customer) {
+        if (nameTerms.isEmpty()) {
+            return true;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        return nameTerms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    /** Strips accents and lower-cases, so that "Mäkinen" and "makinen" compare equal. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
