+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+import org.junit.jupiter.params.ParameterizedTest;
+import org.junit.jupiter.params.provider.ValueSource;
+
+class CustomerFilterTest {
+
+    private static final Customer ADA = new Customer(1, "Ada", "Aaltonen", "ada@example.com", "Finland",
+            CustomerStatus.ACTIVE);
+    private static final Customer MAKINEN = new Customer(2, "Jarno", "Mäkinen", "jarno@example.com",
+            "Finland", CustomerStatus.PENDING);
+    private static final Customer JOSEPHINE = new Customer(3, "Joséphine", "Engberg", "j@example.com",
+            "France", CustomerStatus.CLOSED);
+
+    @Test
+    void allMatchesEveryCustomer() {
+        assertTrue(CustomerFilter.ALL.matches(ADA));
+        assertTrue(CustomerFilter.of("   ", Set.of()).matches(MAKINEN));
+    }
+
+    @Test
+    void everyTermMustMatchTheFirstOrLastName() {
+        assertTrue(CustomerFilter.of("ada aal", Set.of()).matches(ADA));
+        assertTrue(CustomerFilter.of("  aal   ADA  ", Set.of()).matches(ADA));
+        assertFalse(CustomerFilter.of("ada virtanen", Set.of()).matches(ADA));
+    }
+
+    @ParameterizedTest
+    @ValueSource(strings = {"makinen", "MAKINEN", "mäkinen", "Mäkinen"})
+    void nameMatchingIgnoresCaseAndAccents(String typed) {
+        assertTrue(CustomerFilter.of(typed, Set.of()).matches(MAKINEN));
+    }
+
+    @Test
+    void accentsInTheDataAreFoldedToo() {
+        assertTrue(CustomerFilter.of("josephine", Set.of()).matches(JOSEPHINE));
+    }
+
+    @Test
+    void statusesNarrowTheMatch() {
+        assertTrue(CustomerFilter.of("", Set.of(CustomerStatus.ACTIVE)).matches(ADA));
+        assertFalse(CustomerFilter.of("", Set.of(CustomerStatus.PENDING)).matches(ADA));
+        assertTrue(CustomerFilter.of("", Set.of(CustomerStatus.PENDING, CustomerStatus.CLOSED))
+                .matches(MAKINEN));
+    }
+
+    @Test
+    void theNameAndStatusMustBothMatch() {
+        assertFalse(CustomerFilter.of("ada", Set.of(CustomerStatus.PENDING)).matches(ADA));
+    }
+
+    @Test
+    void whitespaceIsNotSignificant() {
+        assertEquals(List.of("ada", "aal"), CustomerFilter.of("  Ada \t  AAL ", Set.of()).nameTerms());
+        assertEquals(List.of(), CustomerFilter.of("   ", Set.of()).nameTerms());
+    }
+}
